const http = require("http");
const fs = require("fs");
const path = require("path");

const root = path.resolve(__dirname, process.env.WEB_ROOT || "public");
const port = Number(process.env.PORT || 3000);
const types = { html: "text/html", css: "text/css", js: "text/javascript", json: "application/json", png: "image/png", jpg: "image/jpeg", svg: "image/svg+xml", ico: "image/x-icon" };

http.createServer((req, res) => {
  const urlPath = decodeURIComponent((req.url || "/").split("?")[0]);
  let file = path.join(root, urlPath);
  if (!file.startsWith(root)) {
    res.writeHead(403);
    return res.end("Forbidden");
  }
  try {
    if (fs.statSync(file).isDirectory()) file = path.join(file, "index.html");
    const data = fs.readFileSync(file);
    const ext = path.extname(file).slice(1).toLowerCase();
    res.writeHead(200, { "content-type": types[ext] || "application/octet-stream" });
    res.end(data);
  } catch {
    res.writeHead(404, { "content-type": "text/plain" });
    res.end("Not found");
  }
}).listen(port, "0.0.0.0", () => console.log(`Serving ${root} on http://0.0.0.0:${port}`));
